// Validate input
const input = $input.first().json;
const body = input.body || {};

const requiredFields = ['project_id', 'stripe_subscription_id', 'new_price_id'];
const missing = requiredFields.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required fields: ${missing.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate proration_behavior if provided
const validProrations = ['create_prorations', 'none', 'always_invoice'];
const proration = body.proration_behavior || 'create_prorations';

if (!validProrations.includes(proration)) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Invalid proration_behavior. Must be one of: ${validProrations.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: body.project_id,
    subscription_id: body.stripe_subscription_id,
    new_price_id: body.new_price_id,
    proration_behavior: proration
  }
}];

// Check project and prepare API call
const dbResults = $('Get Project Config').all();
const inputData = $('Validate Input').first().json;

if (!dbResults || dbResults.length === 0 || !dbResults[0].json.secret_key) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Project '${inputData.project_id}' not found or inactive`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

const secretKey = dbResults[0].json.secret_key;

return [{
  json: {
    found: true,
    authHeader: `Bearer ${secretKey}`,
    subscription_id: inputData.subscription_id,
    new_price_id: inputData.new_price_id,
    proration_behavior: inputData.proration_behavior
  }
}];

// Extract subscription item ID and prepare update
const response = $input.first().json;
const prevData = $('Prepare Request').first().json;

if (response.statusCode !== 200 || !response.body) {
  const error = response.body?.error || {};
  return [{
    json: {
      valid: false,
      error: {
        code: response.statusCode || 404,
        message: error.message || 'Subscription not found',
        type: error.type || 'api_error'
      }
    }
  }];
}

const subscription = response.body;
const items = subscription.items?.data || [];

if (items.length === 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Subscription has no items',
        type: 'invalid_request'
      }
    }
  }];
}

// Get the first item (most subscriptions have one item)
const itemId = items[0].id;

// Build form body using manual encoding (URLSearchParams not available in n8n sandbox)
const encode = (str) => encodeURIComponent(String(str));
const parts = [];
parts.push(`items[0][id]=${encode(itemId)}`);
parts.push(`items[0][price]=${encode(prevData.new_price_id)}`);
parts.push(`proration_behavior=${encode(prevData.proration_behavior)}`);

return [{
  json: {
    valid: true,
    authHeader: prevData.authHeader,
    subscription_id: prevData.subscription_id,
    bodyString: parts.join('&')
  }
}];

// Format response
const response = $input.first().json;

if (response.statusCode === 200 && response.body) {
  const sub = response.body;
  const newPriceId = sub.items?.data?.[0]?.price?.id;

  return [{
    json: {
      success: true,
      subscription_id: sub.id,
      status: sub.status,
      new_price_id: newPriceId,
      current_period_end: sub.current_period_end,
      latest_invoice: sub.latest_invoice
    }
  }];
}

const error = response.body?.error || {};
return [{
  json: {
    success: false,
    error: {
      code: response.statusCode || 500,
      message: error.message || 'Failed to update subscription',
      type: error.type || 'api_error'
    }
  }
}];
